/* comment-bank.js — the Term Questionnaire's Comment Bank (DECISIONS 14,
   docs/questionnaire-plan.md). Data only; teacher/comment-bank.js fills and
   offers it.

   FullVision comment bank, version 1. Moved from tqAutoNarrative in teacher/report-questionnaire.js (src) into the four BC parts; 'new' = written for the four-part structure. Slots: {course}, the data slots, and the student by role: {He}/{he} {him} {His}/{his} {himself}; [a|b] = verb for one person | for they, agreeing with the {he} before it. The realiser (teacher/comment-realiser.js) names the student in the first sentence that mentions them and uses the pronouns after, or the name again when none are on file; a template never writes {name}. Data slots must exist for a sentence to be offered; 'when' must match.

   Here the habit levels in `when` use the stored scale (term_rating.habits):
   1 Rarely, 2 Sometimes, 3 Usually, 4 Consistently, 5 Not Seen. `picture`
   is the term's picture: strong, steady, challenge or early. `grade` is
   the grade sentence's kind (CommentBank.gradeOf): letter, letterClose,
   cminus, cminusClose or proficiency; C- has its own sentences; ie,
   languageGoals and iepGoals replace it (plan PR 3). `path: 'ie'` is a
   Required part of an IE comment; `ieProblem` is what it names as the
   problem (CommentBank.ieProblemOf): missing (work
   labelled Missing), marks (marks on fewer of the class's marked work),
   noMarks (none of it) or low (under 50%). `src` is the
   line of tqAutoNarrative the sentence came from on main before Oct 28 2026,
   or "new".

   `claims` names what a sentence asserts about the student, for
   CommentBank.verify(): grade, even, strength, growthArea, improved,
   slipped, bestPiece, weakPiece, focusWork, nextStep, habits, lateWork,
   notHandedIn, attendance, studentWords, picture, support, marks,
   lowMarks, deadline, ie, newcomer. [] is a
   sentence that asserts nothing, the stand-in for a sentence of its part
   whose claim fails. Every sentence has the field; a test fails without it.

   Grown 2026-10-28 (Colin: "a large, high-quality bank" behind Generate):
   every habit at every level, openings and closers for each picture of the
   term, Overall by the proficiency word (`when.standing`), a competency
   that slipped (`fall`), and more for examples, the student's words,
   next steps, home and class. The old generator's lines were cut as below;
   nothing here brings back a superlative, the teacher's feelings or filler.

   Rewritten 2026-10-30 (plan PR 9, Sentence grammar): every sentence
   names the student through the role slots; titles are quoted by the
   realiser (no "the" before them); one sentence a template; and every
   sentence passes the vocabulary lint (tests/comment-bank-lint.test.js):
   no phrasal verb, idiom, person praise, comparison with classmates,
   sentence over 20 words, or evaluative word outside the controlled
   vocabulary. The six attendance sentences became the plan's one (h60,
   "{He} has missed three classes and been late once this term."); h61
   and h156-h160 were cut.

   Cut 2026-10-30 (plan PR 8): the Support, In Class and At Home groups
   (51 sentences). Support lines are the teacher's own, chosen per class,
   never written for them; one "For the Family" sentence per kind of class
   replaces the At Home ones, which sent families back to worksheets.

   Cut 2026-10-30 (Colin: Generate never uses observations): the eight
   "From Your Notes" sentences that quoted an observation (n40-n42,
   n141-n143, g07, g114).

   Replaced 2026-10-30 (plan PR 7, habits summary): the 186 sentences that
   said one or two habits at a level, or listed every strong and growing
   habit (From Your Ratings, Completes Work and Takes Part, and one group
   per habit), and n23, which named the growing habits again. The habits
   part is now one summary sentence (hs01-hs10), plus the IE comment's
   strengths (hs11-hs12), Support and Attendance.

   Cut 2026-10-31 (the drift audit against the plan): the Work to Revisit
   group (g06, g110, g111, g207, g212, g218), which told families to redo
   a worksheet; every Examples From Work sentence but the plan's best-piece
   sentence n36 (n30-n35, n135-n140, n205, n206, n211, n212, n217, n218,
   n223, n228), which printed a mark per piece, named weak pieces or
   inferred "clear understanding" from a mark; the Looking Ahead group
   (w06-w09, w117-w129, w206, w212, w218, w222, w226), which no draft step
   used and which made claims about the future; and the other sentences
   the future-claim lint flags (n131, n113, g02, g04, g05, g106, g205,
   g213). Nine subject Overall sentences (n203, n204, n210, n221, n222,
   n227, n232, n236, n300) now state the next step instead of what practice
   "will build".

   Cut 2026-10-31 (the engine now drafts the plan's eight parts only):
   the Openings (n01-n09, n101-n112), Growth This Term (n20-n22, n129,
   n130, n132-n134) and In the Student's Words (n50-n53, n144-n147, g08,
   g112, g113, w03) groups, whose draft steps are gone; the even-results
   sentences (n128, n13, n127); the Overall sentences that printed bare
   competency labels for strengths and growth areas (n10, n12, n126); and
   the rise/fall next steps (g108, g109). {strengths} is now one or two
   skills from the competency-to-skill table, as the next step is, so the
   strengths sentences (n11, n14, n15, n16, n115, n116, n118, n121, n124)
   say "{he} can {strengths}"; n16 takes {strength}, the first alone.

   Cut 2026-11-01 (sim-729): the 44 Overall sentences that stated the
   standing word (n114-n125, n201-n239, n300). The grade sentence says the
   standing once (DRAFT_STEPS `says`), so they could never be offered. The
   Work Habits frames hs05-hs08, hs10, hs29, hs30 and hs32-hs37 no longer
   say "next": the comment's one next step is the Next Step sentence.
   The climb frames n411, n413 and n414 are shorter, so they fit with one
   skill in {strengths}: the realised sentence counts against 20 words.

   Grown 2026-11-01 (Colin: "significantly more" sentences, "too little
   variation"): For the Family went from 18 sentences to 291. Five for every
   skill in the competency-to-skill table (teacher/comment-bank.js SKILLS),
   bound to the next step by `when.nextSkill` and tagged to the kind of class
   whose table names it, so the family gets a way to help with the step the
   comment names; and 10 general sentences for any class plus six for each
   kind. Every one is an invitation a family can take at the kitchen table
   with no subject knowledge, no homework, no supervising, and nothing
   assumed about the home. Each passed the lint and the acceptability
   checklist (families, students, teachers, the Ministry) before it shipped.

   Grown 2026-11-01 (Colin: "too little variation"), the habits part: more
   frames for each condition with the facts unchanged. Work Habits
   hs17-hs37 (excellent, good, one habit to build, two), Strong Habits
   hs13-hs15 ({strongHabits}, the habits rated Consistently as a verb
   phrase), Attendance h61-h78 ({absentClasses}, {lateTimes}; absences
   only, lates only, both) and Not Handed In m02-m21 ({missingTitle},
   {missingTitles}, {missingCount} with missingMany, {missingGroup}). The
   habit names still come only through the summary's slots. hs06 and hs09
   were reworded so no frame's fixed words sit inside another's (the usage
   pattern counted them as one); hs16 and hs22 were cut (they opened like
   hs01 and hs03). The review of #595 (Nov 1): the "all six / every one"
   frames need habitsAllSeen (no habit Not Seen) so they are literally
   true; hs19, h61, h67 and h73 were cut (two ideas, or h60's own
   wording); m06, m11, m12, m15, m17, m21, hs28, hs35, hs36, h66 and h77
   were reworded for structure or plainness. Every sentence was checked
   against the acceptability checklist (Ministry, families, students,
   teachers).

   Grown 2026-11-01 from the school's own comment bank (Colin): the codes
   that pass the four-audience checklist are adapted as grade frames
   (scr), strengths frames (scn) and next steps per skill (scg), each
   with `src` "GHS <code>"; docs/comment-bank-school-codes.md classifies
   every code, and
   nothing rejected is reproduced here. The school's ELL lines became the
   teacher-ticked Language Goals list (teacher/comment-bank.js).

   Cut from tqAutoNarrative, and why:
     572-577: Superlatives and teacher-centred praise ('outstanding', 'makes teaching rewarding', 'can't say enough good things').
     581, 585: Teacher's feelings ('I've been really pleased', 'made me proud').
     598-600, 604-606: Repeats of kept openings, or talk about the teacher ('I want to be honest about what I see').
     634-700: Built on character traits and disposition labels the questionnaire no longer collects; the habit rows replace them.
     705-706, 714-720: Filler ('I appreciate your willingness to show up and try'); growth is now said from data.
     730, 734, 739, 744, 748, 752-753, 757, 761, 766, 770, 774, 778, 782, 786, 790, 794: Repeats of a kept sentence, comparisons ('one of our most', 'sets a great example') or 'I'd love / I know there's more inside'.
     799: Empty fallback.
     858-867 letter versions duplicated: One letter-grade frame kept (n14); the rest repeat it.
     893-921: Statistics about spread ('the data shows real variation') with no meaning for families.
     932-935, 941, 948: Superlatives ('really shines') or repeats.
     959-960, 966, 976, 980-981, 988-993: Repeats, 'struggled', or praise words ('standout', 'excellent pieces of work').
     1000-1001, 1011: Bridges with no content.
     1047-1051, 1056-1057, 1064: 'I love to see', 'says it better than I could' and other framing about the teacher.
     1075-1134: Counts of observations, lists of quoted notes, and talk about the teacher's notes; families need one example, not a tally.
     1145-1191 (most): Praise for self-awareness ('shows maturity', 'I appreciate that honesty'); two frames kept as n52-n53.
     1223-1233: Wrappers for the concern list ('It's a small thing relative to all the positives'); the concerns themselves are kept as habit sentences.
     1242-1243, 1254, 1256, 1266-1267, 1275: Promises and filler ('I'm excited to see how she responds', 'push to the next level').
     1282-1312 (most): Closers by student type: superlatives, 'a joy to have in class', 'Stay tuned'. Three neutral ones kept (w07-w09).
*/
