    // Lane H (gen/bank-subjects, 2026-11-01; Colin: the thin kinds of
    // class). The skill table grew by 43 skills: Math (estimating,
    // patterns, graphs, notation, word problems, procedures), Career Life
    // Education (influences, résumés and interviews, budgeting,
    // post-secondary options), ADST for every course family (safety,
    // food preparation, sewing, cutting and joining, drafting, coding,
    // media design, business, materials, teamwork), PE (outdoor, game
    // strategy, healthy eating, healthy relationships, substance use,
    // pacing, managing stress), Arts (planning a piece, using feedback,
    // elements and principles, performing, reading notation, camera and
    // light, documenting the process) and a new Languages family
    // (listening, speaking, reading, writing, vocabulary, grammar,
    // culture, communicating, understanding). Each skill has four Next
    // Step frames in lane C's shape (`needs: ['nextSkill']`,
